update.title:
/usr/bin/bash -lc "cat > fizzbuzz.js <<'EOF'
function fizzbuzz(n) {
  return Array.from({ length: n }, (_, index) => {
    const number = index + 1;
    return (number % 3 === 0 ? 'Fizz' : '') +
      (number % 5 === 0 ? 'Buzz' : '') || String(number);
  });
}

module.exports = { fizzbuzz };
EOF
cat > fizzbuzz.test.js <<'EOF'
const test = require('node:test');
const assert = require('node:assert/strict');
const { fizzbuzz } = require('./fizzbuzz');

test('returns FizzBuzz strings from 1 through n', () => {
  assert.deepEqual(fizzbuzz(15), [
    '1', '2', 'Fizz', '4', 'Buzz', 'Fizz', '7', '8', 'Fizz',
    'Buzz', '11', 'Fizz', '13', '14', 'FizzBuzz',
  ]);
});

test('returns an empty array for zero', () => {
  assert.deepEqual(fizzbuzz(0), []);
});

test('includes the upper bound', () => {
  assert.deepEqual(fizzbuzz(1), ['1']);
  assert.equal(fizzbuzz(30)[29], 'FizzBuzz');
});
EOF
node --test"

